ALTER TABLE "session_segments" DROP CONSTRAINT "session_segment_bounds";--> statement-breakpoint
ALTER TABLE "session_segments" ADD CONSTRAINT "session_segment_bounds" CHECK ("session_segments"."sequence_index" between 0 and 49 and "session_segments"."segment_type" in ('original','studio') and "session_segments"."ended_at">="session_segments"."started_at" and "session_segments"."duration_seconds">=0 and "session_segments"."rounds">0 and "session_segments"."participant_count" between 0 and 1500 and "session_segments"."submissions">=0 and "session_segments"."votes">=0 and jsonb_array_length("session_segments"."results")<=300);